def palavras(t):
    # "pré-\ncorreção" vem partido no PDF: o hífen de fim de linha é juntado antes de contar.
    return Counter(re.findall(r'[\wº§]+', re.sub(r'-\s*\n\s*', '-', t).replace('-', ' ').lower()))

def corrigir(db):
    (origem,), = db.execute("SELECT texto FROM unidade WHERE secao='Anexo II' AND localizador='Quadro de classificação de risco'")
    novo = '\n\n'.join(nivel + '\n' + '\n'.join(r + ': ' + c for r, c in zip(ROTULOS, colunas)) for nivel, *colunas in QUADRO)
    cabecalho = 'Nível de risco ' + ' '.join(ROTULOS)
    a, b = palavras(origem), palavras(cabecalho + ' ' + ' '.join(' '.join(q) for q in QUADRO))
    assert a == b, ('quadro do Anexo II difere do texto de origem', a - b, b - a)
    db.execute("UPDATE unidade SET texto=?, tipo='quadro' WHERE secao='Anexo II' AND localizador='Quadro de classificação de risco'", (novo,))
    for colado, certo in (('ANEXO IIGUIA DE INTERPRETAÇÃO DA CLASSIFICAÇÃO DE RISCO ', 'ANEXO II\nGUIA DE INTERPRETAÇÃO DA CLASSIFICAÇÃO DE RISCO\n'),
                          ('ANEXO IGLOSSÁRIO', 'ANEXO I\nGLOSSÁRIO')):
        n = db.execute("UPDATE unidade SET texto=replace(texto, ?, ?) WHERE texto LIKE ?", (colado, certo, '%' + colado + '%')).rowcount
        assert n == 1, (colado, n)
